export interface CustomerDao {                       // checked contract
  find(id: number): Promise<Customer | null>;
  add(c: Customer): Promise<void>;
}
export class PgCustomerDao implements CustomerDao {
  constructor(private readonly pool: Pool) {}        // injected pool
  async find(id: number): Promise<Customer | null> {
    const { rows } = await this.pool.query<CustomerRow>(
      'SELECT id, name, version FROM customer WHERE id = $1', [id]);
    return rows[0] ? toCustomer(rows[0]) : null;     // row type -> domain type
  }
}

